/* Version-1 backups remain readable; new backups also keep the project chat/files. */
function backup(){download('PINA-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({format:'pina-fieldguide',version:1,exportedAt:new Date().toISOString(),meta,work,trail,pipProject:{files:chat3.files,messages:chat3.messages,material:chat3.material,type:chat3.type,route:chat3.route,walk:chat3.walk,tool:chat3.tool,field:chat3.field}},null,2),'application/json');toast('Project backup downloaded.');}
function parseProject3(data){
 if(data.format!=='pina-fieldguide'||data.version!==1||!data.work||typeof data.work!=='object'||Array.isArray(data.work)||!data.meta||typeof data.meta.project!=='string')throw Error('Choose a valid PINA backup.');
 const clean={};for(const[k,v]of Object.entries(data.work)){if(k==='ledger'){if(!Array.isArray(v)||v.length>500||v.some(r=>!Array.isArray(r)||r.length!==6||r.some(x=>typeof x!=='string')))throw Error('The ledger format is invalid.');clean.ledger=v;}else if((/^s(?:[0-9]|1[0-4])_[a-zA-Z0-9_]+$/.test(k)||['v2_route_message','v2_migration'].includes(k))&&['string','number','boolean'].includes(typeof v))clean[k]=v;}
 if(!clean.ledger)clean.ledger=[['','','','','','']];
 const m={project:data.meta.project.slice(0,120),displayName:typeof data.meta.displayName==='string'?data.meta.displayName.slice(0,60):'Aarshi',pins:(data.meta.pins||[]).filter(n=>Number.isInteger(n)&&n>=0&&n<7),last:1,studioProgress:{},pipRouteEntries:(data.meta.pipRouteEntries||[]).filter(e=>typeof e.title==='string'&&typeof e.text==='string').map(e=>({title:e.title.slice(0,200),text:e.text.slice(0,300000),date:String(e.date||'').slice(0,60),tools:Array.isArray(e.tools)?e.tools.filter(id=>Number.isInteger(id)&&V2.tools[id]):[]}))};
 for(let id=0;id<15;id++){const screen=data.meta.studioProgress?.[id]?.screen;if(['context','notes','output'].includes(screen)||Number.isInteger(Number(screen))&&Number(screen)>=0&&Number(screen)<v2Tool(id).steps.length)m.studioProgress[id]={screen};}
 if(Array.isArray(data.meta.v2Route?.tools)&&data.meta.v2Route.tools.every(id=>Number.isInteger(id)&&V2.tools[id]))m.v2Route={key:String(data.meta.v2Route.key||'saved'),tools:data.meta.v2Route.tools};
 const t={passed:[],answers:{},maps:{}};if(data.trail&&typeof data.trail==='object'){t.passed=(data.trail.passed||[]).filter(id=>Number.isInteger(id)&&V2.tools[id]);for(let id=0;id<15;id++){const a=data.trail.answers?.[id],map=data.trail.maps?.[id];if(Number.isInteger(a)&&a>=0&&a<3)t.answers[id]=a;if(Array.isArray(map))t.maps[id]=map.filter(n=>Number.isInteger(n)&&n>=0&&n<V2_LESSONS[id].length);}}
 const p=data.pipProject,project={files:[],messages:[],material:'',type:'auto',route:null,walk:null,tool:null,field:''};
 if(p){if(!Array.isArray(p.files)||p.files.length>5)throw Error('The project file list is invalid.');project.files=p.files.map(f=>{if(typeof f.name!=='string')throw Error('A project filename is invalid.');if(typeof f.text==='string'&&f.text.length<=60000)return {name:f.name.slice(0,140),text:f.text};if(!f.attachment||!['application/pdf','image/png','image/jpeg','image/webp'].includes(f.attachment.mime)||typeof f.attachment.data!=='string'||f.attachment.data.length>7000000||!/^[A-Za-z0-9+/]+={0,2}$/.test(f.attachment.data))throw Error('An attachment is invalid.');return {name:f.name.slice(0,140),attachment:{mime:f.attachment.mime,data:f.attachment.data}};});project.messages=Array.isArray(p.messages)?p.messages.slice(-50).filter(m=>m&&['user','assistant'].includes(m.role)&&(!Object.hasOwn(m,'tool')||m.tool===null||Number.isInteger(m.tool)&&V2.tools[m.tool])).map(m=>({...m,...(m.reply?{reply:{...m.reply,tools:Array.isArray(m.reply.tools)?m.reply.tools.filter(id=>Number.isInteger(id)&&V2.tools[id]):[],suggestions:Array.isArray(m.reply.suggestions)?m.reply.suggestions.filter(s=>pipV3Allowed(m.tool).includes(s.field)&&typeof s.value==='string'):[]}}:{})})):[];project.material=String(p.material||'').slice(0,36000);project.type=String(p.type||'auto');project.route=Array.isArray(p.route?.tools)&&p.route.tools.every(id=>Number.isInteger(id)&&V2.tools[id])?p.route:null;project.tool=Number.isInteger(p.tool)&&V2.tools[p.tool]?p.tool:null;project.field=String(p.field||'').slice(0,80);project.walk=Number.isInteger(p.walk?.tool)&&V2.tools[p.walk.tool]&&Number.isInteger(p.walk.index)&&p.walk.index>=0?{tool:p.walk.tool,index:Math.min(p.walk.index,chatWalkFields(p.walk.tool).length)}:null;}
 return {work:clean,meta:m,trail:t,project};
}
const projectImport3=document.querySelector('#import-file');if(typeof projectImport3?.cloneNode==='function'){const input=projectImport3.cloneNode(false);projectImport3.replaceWith(input);input.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>45*1024*1024)throw Error('Choose a PINA backup up to 45 MB.');const data=parseProject3(JSON.parse(await file.text()));if(!confirm('Replace the active project, notes, files and chat with this backup? Export the current project first if you need it.'))return;if(!persist(WORK_KEY,data.work)||!persist(META_KEY,data.meta)||!persist(TRAIL_KEY,data.trail))throw Error('This browser could not save the backup. Your file remains safe.');work=data.work;meta=data.meta;trail=data.trail;Object.assign(chat3,data.project,{open:false,settings:false});await chatPersist();savedScrolls.clear();savedPanelScrolls.clear();route();toast('Your complete project is restored.');}catch(err){toast(err.message||'The backup could not be restored.');}finally{e.target.value='';}});}
const restartProject3=restartDialog;restartDialog=function(scope){restartProject3(scope);if(scope!=='all')return;const dialog=document.querySelector('#restart-dialog'),button=dialog.querySelector('[value=restart]'),old=button.onclick;dialog.querySelector('p').textContent='This clears every project’s answers, edited drafts, combined notebook entries, project files and chat in this browser. Export a backup first if you need them.';button.onclick=async e=>{old(e);if(!dialog.open){delete meta.pipRouteEntries;delete meta.v2Route;saveMeta();Object.assign(chat3,{files:[],messages:[],material:'',draft:'',type:'auto',route:null,walk:null,tool:null,field:'',open:false});await chatPersist();chatRender();}};};
route();
